<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue';
import { invoke, useI18n } from '../uiPorts';
export type HunterExpansion = { id:string;kind:string;target:string;query:string;status:string;pageSize:number;nextPage:number;total:number|null;received:number;uniqueRows:number;rejected:number;spentPoints:number;costUnknown:boolean;reason:string;account?:{rest_free_point?:number;rest_equity_point?:number};startDate?:string;endDate?:string;pages?:{page:number;state:string;points:number|null;consumeQuota:string;restQuota:string;returned:number;accepted:number;rejected:number}[] };
const props=defineProps<{projectId?:number;items?:HunterExpansion[]}>();const emit=defineEmits<{changed:[]}>();
const busy=ref(''),error=ref('');let generation=0,disposed=false;
watch(()=>props.projectId,()=>{generation++;busy.value='';error.value='';});onUnmounted(()=>{disposed=true;generation++;});
const {tr}=useI18n();
const labels=computed<Record<string,string>>(()=>({running:tr('正在自动翻页','Auto paging'),stopping:tr('正在暂停','Pausing'),paused:tr('已暂停，可继续','Paused; can resume'),completed:tr('已遍历报告的全部分页','All reported pages traversed'),unknown:tr('远端结果 / 扣费待核对','Remote result / charge to be reconciled'),partial:tr('有未完成或未验证部分','Some parts unfinished or unverified'),quota:tr('积分或额度不足','Insufficient points or quota'),provider_limit:tr('平台限制，未完成','Platform limit; not finished'),interrupted:tr('已中断，保留游标','Interrupted; cursor kept')}));
async function act(action:'stop'|'resume',id:string){if(!props.projectId||busy.value)return;const p=props.projectId,g=generation;busy.value=id;error.value='';try{await invoke(`${action}_hunter_expansion`,{projectId:p,queryId:id});if(!disposed&&g===generation)emit('changed');}catch(e){if(!disposed&&g===generation)error.value=String(e);}finally{if(!disposed&&g===generation)busy.value='';}}
</script>
<template>
<section v-if="items?.length" class="hunter-progress" data-testid="hunter-expansion-progress">
<h4>{{tr('Hunter 精确关联 · 分页与积分','Hunter exact correlation · pages and points')}}</h4>
<article v-for="item in items" :key="item.id" :data-query-id="item.id">
<header><strong>{{item.target}}</strong><span :data-hunter-status="item.status">{{labels[item.status]||item.status}}</span></header>
<p><code>{{item.query}}</code></p><p v-if="item.startDate">{{tr(`时间范围：${item.startDate} 至 ${item.endDate}`,`Date range: ${item.startDate} to ${item.endDate}`)}}</p>
<p>{{tr(`累计返回 ${item.received} 条（含重复） · 本查询去重后 ${item.uniqueRows} 条 · 平台报告 ${item.total??'未知'} 条 · 下一页 ${item.nextPage}`,`${item.received} returned in total (incl. duplicates) · ${item.uniqueRows} unique for this query · platform reports ${item.total??'unknown'} · next page ${item.nextPage}`)}}<span v-if="item.pageSize">{{tr(`（每页 ${item.pageSize} 条）`,` (${item.pageSize} per page)`)}}</span></p>
<p><strong>{{tr(`已核对消耗 ${item.spentPoints} 积分`,`Verified spend: ${item.spentPoints} points`)}}</strong><span v-if="item.costUnknown" class="form-error">{{tr(' · 另有消耗未确认，不能当作 0',' · Some spend is unconfirmed and must not be treated as 0')}}</span>{{tr(` · 免费余额 ${item.account?.rest_free_point??'未报告'} · 权益余额 ${item.account?.rest_equity_point??'未报告'}`,` · Free balance ${item.account?.rest_free_point??'not reported'} · Entitlement balance ${item.account?.rest_equity_point??'not reported'}`)}}</p>
<p role="status">{{item.reason}}</p><p v-if="item.rejected" class="form-error">{{tr(`${item.rejected} 条记录未通过精确关联 / 身份核对，原始页已保留。`,`${item.rejected} records failed exact correlation / identity checks; the raw pages are kept.`)}}</p>
<div class="hunter-actions"><button v-if="['running','stopping'].includes(item.status)" class="button danger compact" :disabled="!!busy||item.status==='stopping'" @click="act('stop',item.id)">{{tr('暂停自动翻页','Pause auto paging')}}</button><button v-else-if="['paused','quota','partial','interrupted'].includes(item.status)" class="button secondary compact" :disabled="!!busy" @click="act('resume',item.id)">{{tr('从保存的游标继续','Resume from saved cursor')}}</button></div>
<details v-if="item.pages?.length"><summary>{{tr('最近 20 页回执（所有已收页均保留）','Receipts for the last 20 pages (all received pages are kept)')}}</summary><div class="hunter-pages"><table><thead><tr><th>{{tr('页码','Page')}}</th><th>{{tr('状态','Status')}}</th><th>{{tr('返回 / 新增','Returned / added')}}</th><th>{{tr('积分消耗','Points spent')}}</th><th>{{tr('平台余额回执','Platform balance receipt')}}</th></tr></thead><tbody><tr v-for="page in item.pages" :key="page.page"><td>{{page.page}}</td><td>{{page.state}}</td><td>{{page.state==='sending'?tr('未确认','Unconfirmed'):`${page.returned} / ${page.accepted}`}}</td><td>{{page.consumeQuota||(page.points==null?tr('未确认','Unconfirmed'):page.points)}}</td><td>{{page.restQuota||tr('未报告','Not reported')}}</td></tr></tbody></table></div></details>
</article><p v-if="error" class="form-error" role="alert">{{error}}</p>
</section>
</template>
<style scoped>.hunter-progress{margin-top:16px}.hunter-progress article{padding:14px;border:1px solid var(--line,var(--ui-line));border-radius:var(--radius-md);margin:10px 0}.hunter-progress header{display:flex;gap:12px;justify-content:space-between;overflow-wrap:anywhere}.hunter-progress p{font-size:var(--text-body);margin:8px 0;overflow-wrap:anywhere}.hunter-progress header span{color:var(--muted);font-size:var(--text-meta);flex-shrink:0}.hunter-progress header [data-hunter-status=completed]{color:color-mix(in srgb, var(--green) 82%, var(--ui-ink))}.hunter-progress header [data-hunter-status=unknown],.hunter-progress header [data-hunter-status=partial]{color:color-mix(in srgb, var(--amber) 82%, var(--ui-ink))}.hunter-actions{display:flex;gap:8px;margin:8px 0}.hunter-pages{overflow:auto}.hunter-pages table{width:100%;font-size:var(--text-meta);border-collapse:collapse}.hunter-pages td,.hunter-pages th{padding:8px;border-bottom:1px solid var(--line,var(--ui-line));text-align:left}</style>
